From 460367744be8b056cf170de3fd12bd7021fa7e0b Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 19:56:41 +0100
Subject: [PATCH] ToolTipDialog: scroll the content when the wheel is over the
 padding

Tooltips lost Dialog's forwarding of wheel events from the frame padding
to the content when they moved to PopupPlasmaWindow, so a long grouped
task tooltip couldn't be scrolled at its edges. Forward them again.

BUG: 493016
---
 src/declarativeimports/core/tooltipdialog.cpp | 15 +++++++++++++++
 1 file changed, 15 insertions(+)

diff --git a/src/declarativeimports/core/tooltipdialog.cpp b/src/declarativeimports/core/tooltipdialog.cpp
index 73b7675df..1c75b08fe 100644
--- a/src/declarativeimports/core/tooltipdialog.cpp
+++ b/src/declarativeimports/core/tooltipdialog.cpp
@@ -6,11 +6,13 @@

 #include "tooltipdialog.h"

+#include <QCoreApplication>
 #include <QDebug>
 #include <QFile>
 #include <QPlatformSurfaceEvent>
 #include <QQmlEngine>
 #include <QQuickItem>
+#include <QWheelEvent>

 #include <KWindowSystem>

@@ -101,6 +103,19 @@ bool ToolTipDialog::event(QEvent *e)
         }
     } else if (e->type() == QEvent::Leave) {
         dismiss();
+    } else if (e->type() == QEvent::Wheel && e->spontaneous() && mainItem()) {
+        // Fitts' law: scrolling over the frame's padding scrolls the content closest to the cursor
+        auto we = static_cast<QWheelEvent *>(e);
+        const QRectF itemRect(mainItem()->mapToScene(QPointF(0, 0)), mainItem()->size());
+        if (!itemRect.contains(we->position())) {
+            const QPointF pos(qBound(itemRect.left(), we->position().x(), itemRect.right() - 1),
+                              qBound(itemRect.top(), we->position().y(), itemRect.bottom() - 1));
+            const QPointF globalPos = pos + position();
+            QWheelEvent we2(pos, globalPos, we->pixelDelta(), we->angleDelta(), we->buttons(), we->modifiers(), we->phase(), we->inverted(), we->source());
+            we2.setTimestamp(we->timestamp());
+            QCoreApplication::sendEvent(this, &we2);
+            return true;
+        }
     }

     return PopupPlasmaWindow::event(e);
-- 
